# Approach 1: `RedisTemplate`

### Redis Configuration

```java
@Configuration
public class RedisConfig {

    @Bean
    public RedisTemplate<String, Object> redisTemplate(
            RedisConnectionFactory connectionFactory) {

        RedisTemplate<String, Object> template = new RedisTemplate<>();

        template.setConnectionFactory(connectionFactory);

        template.setKeySerializer(new StringRedisSerializer());

        template.setValueSerializer(
                new GenericJackson2JsonRedisSerializer()
        );

        return template;
    }
}
```

### Service

```java
@Service
@RequiredArgsConstructor
public class UserService {

    private final RedisTemplate<String, Object> redisTemplate;

    private static final String USER_KEY = "user:";

    public User getUser(Long id) {

        String key = USER_KEY + id;

        // 1. Check Redis
        User cachedUser =
                (User) redisTemplate.opsForValue().get(key);

        if (cachedUser != null) {
            System.out.println("Returning from Redis");
            return cachedUser;
        }

        // 2. DB call
        User user = findFromDatabase(id);

        // 3. Save in Redis
        redisTemplate.opsForValue()
                .set(
                    key,
                    user,
                    Duration.ofMinutes(10)
                );

        return user;
    }

    public User updateUser(Long id, User user) {

        // Update DB
        User updatedUser = updateDatabase(id, user);

        // Invalidate cache
        redisTemplate.delete(USER_KEY + id);

        return updatedUser;
    }

    public void deleteUser(Long id) {

        deleteFromDatabase(id);

        // Invalidate cache
        redisTemplate.delete(USER_KEY + id);
    }

    private User findFromDatabase(Long id) {
        // repository.findById(id)
        return null;
    }

    private User updateDatabase(Long id, User user) {
        return user;
    }

    private void deleteFromDatabase(Long id) {
